insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('JP:accountant','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 038-03 covers employee accounting work including ledgers, monthly/year-end statements and tax-document preparation, while excluding statutory CPA audit work.','entry_level_basis','Accounting, commerce and business study support entry; one reviewed Japanese accounting programme is retained as direct.','qualification_note','General employee accountants do not require the 公認会計士 credential merely to work in accounting.','market_scope','Market enrichment is deferred until all country occupation foundations are complete.','visa_scope','No occupation-specific visa credit is assigned in the foundation phase.'),'2026-08-10'),
('JP:financial-analyst','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 013-99 explicitly includes 証券アナリスト and professional financial-analysis work, used here only for the financial-analyst scope.','entry_level_basis','Finance, economics, accounting and quantitative business study are common foundations; five reviewed programmes remain related rather than job guarantees.','qualification_note','No single statutory personal licence covers every financial analyst role.','market_scope','Salary, vacancies, shortage and growth are intentionally unscored pending later market enrichment.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:business-analyst','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Non-ICT Business Analyst duties overlap MHLW 013-99 management-consulting work and 033-03 planning/research analysis; neither code alone represents the full canonical occupation.','entry_level_basis','Business, economics, analytics and management study can support entry; three approved programmes are retained as related pathways.','qualification_note','There is no universal statutory Business Analyst licence.','market_scope','No blended management-consulting/planning labour series is fabricated.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:supply-chain-analyst','2026-08-10',0,0,0,0,10,0,0,0,5,15,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','Japan has no standalone MHLW Supply Chain Analyst code; relevant planning, production/material planning and logistics-management administration appear across 033-03, 039-01 and 039-02.','entry_level_basis','Industrial engineering, logistics, operations, economics and business study are relevant; two approved programmes remain related.','qualification_note','No universal statutory Supply Chain Analyst licence applies.','market_scope','Operational logistics and production-office statistics are not merged into an analyst-only series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:human-resources-specialist','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 033-02 directly covers recruitment, evaluation, payroll, training, welfare and labour-management HR administration.','entry_level_basis','Business, HR, psychology and related study can support entry, alongside employer-based development.','qualification_note','No universal statutory HR specialist licence is required.','market_scope','Market data remain unscored until the common enrichment phase.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:marketing-specialist','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW 033-03 explicitly includes marketers, marketing research, web marketing and sales-promotion planning, making it the direct planning/analysis anchor for the canonical Marketing Specialist.','entry_level_basis','Marketing, communications, business and analytics study plus campaign/project evidence support entry; two approved programmes remain related.','qualification_note','No universal statutory Marketing Specialist licence applies.','market_scope','Advertising-sales and general sales codes are not substituted for marketing-specialist market evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:auditor','2026-08-10',0,0,0,0,10,0,0,0,2,12,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','The neutral Auditor career spans external statutory financial audit under 013-01 公認会計士 and internal audit under 033-01 内部監査員, so no single code is claimed.','entry_level_basis','Accounting and business study can lead toward audit work; the one approved accounting programme is related and does not confer CPA status.','qualification_note','Statutory CPA audit work requires the 公認会計士 qualification/registration framework, while internal audit does not have the same universal statutory registration.','market_scope','External and internal audit markets are not merged into a fabricated exact series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:project-manager','2026-08-10',0,0,0,0,10,0,0,0,3,13,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','MHLW has a specific 010-03 IT Project Manager and 035-99 PMO support role, but no one cross-industry Project Manager code matching the canonical career.','entry_level_basis','Project-management entry is sector dependent and usually combines domain knowledge with planning, coordination and delivery experience; five reviewed programmes remain related.','qualification_note','No universal statutory cross-industry Project Manager licence applies.','market_scope','IT project-management data are not presented as the generic cross-industry market.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10')
